import{_ as t,c as n,j as e,a as _,o as l}from"./chunks/framework.CqbvlPrP.js";const u=JSON.parse('{"title":"第二百二十九章 没有永远存在的事物","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/229第二百二十九章 没有永远存在的事物.md","filePath":"meditation/巴利文大藏经/229第二百二十九章 没有永远存在的事物.md"}'),r={name:"meditation/巴利文大藏经/229第二百二十九章 没有永远存在的事物.md"};function o(s,a,i,d,p,c){return l(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百二十九章-没有永远存在的事物",tabindex:"-1"},[_("第二百二十九章 没有永远存在的事物 "),e("a",{class:"header-anchor",href:"#第二百二十九章-没有永远存在的事物","aria-label":'Permalink to "第二百二十九章 没有永远存在的事物"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应15经/凡无常者经(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！物质事物、物质身体是随时在变化的，是无法永恒保持不变的，是无法永远存在的。既然物质事物、物质身体随时在变化，无法永远存在，无法永恒的保持不变，那么当世间人的物质身体生病、衰老、临死的时候，当世间人失去他们拥有的物质事物，或者当他们拥有的物质事物衰败、灭亡、消失的时候，他们就会产生痛苦。当世间人的物质身体死亡、腐烂、消失的时候，当世间人失去他们拥有的物质事物，或者当他们拥有的物质事物灭亡、消失的时候，他们就会明白世间实际上并没有一个永远存在的我，没有永恒不变的我，没有真实不变的我。他们就会明白世间实际上也没有自己可以永远拥有的物质事物存在。他们就会由此开启正确的智慧，彻底的明白：「世间的物质事物不是我所拥有的，我不是这个世间的物质身体，这个世间的物质身体不是真实不变的我。」简单的说就是，他们会认为：「这不是我的，我不是这个，这不是真实不变的我。」",-1),e("p",null,"比丘们！同样的道理，感受、念想、行为、认识、分别、判断是随时在变化的，是无法永恒保持不变的，是无法永远存在的。既然感受、念想、行为、认识、分别、判断随时在变化，无法永远存在，无法永恒的保持不变，那么当世间人的感受、念想、行为、认识、分别、判断让他们不满意、不快乐、不开心的时候，或者当世间人失去让他们满意、快乐、开心的感受、念想、行为、认识、分别、判断的时候，他们就会产生痛苦。当世间人的各种感受、念想、行为、认识、分别、判断彻底消失的时候，他们就会明白世间实际上并没有一个永远存在的我，没有永恒不变的我，没有真实不变的我。他们就会明白世间实际上也没有自己可以永远拥有的感受、念想、行为、认识、分别、判断的存在。他们就会由此开启正确的智慧，彻底的明白：「感受、念想、行为、认识、分别、判断不是我所拥有的，我不是这个感受、念想、行为、认识、分别、判断，这个感受、念想、行为、认识、分别、判断不是真实不变的我。」简单的说就是，他们会认为：「这不是我的，我不是这个，这不是真实不变的我。」",-1),e("p",null,"比丘们！当你们有了这个正确的见解，那就是已经受到了如来的教导。已经受到如来教导的圣弟子们，他们不会执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断，当他们不执着和挂念这些事物的时候，就不会被这些事物束缚捆绑，就不会因为这些事物胡思乱想、胡作非为，就不会让这些事物污染自己内心清净的境界。当他们彻底从这些事物中解脱出来的时候，彻底的灭尽一切烦恼和痛苦的时候，他们就开启了解脱的智慧，他们就证悟了解脱的果位，他们自己就明白了：「从这一世开始已经不会再出生在世间了。行为、言语、念想的修行已经圆满，应该做的事情已经做好，不会再有喜怒哀乐等等烦恼和痛苦的轮回状态了，不会再出生在世间了，已经彻底从生死轮回中解脱出来。」”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const f=t(r,[["render",o]]);export{u as __pageData,f as default};
